import { AssetManager } from '@game-studio/asset-manager';
import gsap from 'gsap';
import { DEFAULT_CROSSFADE_OPTIONS, DEFAULT_FADE_OPTIONS, DEFAULT_MUSIC_OPTIONS, DEFAULT_SFX_OPTIONS } from './default-options';
import { DynamicTrackController } from './dynamic-track-controller';
import { logAudioError, logAudioInfo } from './internal';
import { SoundInstance } from './sound-instance';
import { SoundManager } from './sound-manager';
import { ICrossfadeOptions, ICrossFadeResponse, IDynamicSoundOptions, IFadeOptions, ISoundPlayCategoryOptions, ISoundPlayOptions } from './types';

export class SoundController {
    private activeTrackList: Map<number, SoundInstance>;
    private disablePlaybackBeforeUnlock: boolean;

    protected categoryDynamicTrackControllers: Record<string, DynamicTrackController> = {};

    protected categoryMutes: Record<string, boolean> = {
        sfx: false,
        music: false
    };

    protected categoryVolumes: Record<string, number> = {
        sfx: 1,
        music: 1
    };

    protected categoryOptions: Record<string, ISoundPlayOptions> = {
        sfx: DEFAULT_SFX_OPTIONS,
        music: DEFAULT_MUSIC_OPTIONS
    };

    public constructor(disablePlaybackBeforeUnlock: boolean = false) {
        this.activeTrackList = new Map();
        this.disablePlaybackBeforeUnlock = disablePlaybackBeforeUnlock;
    }

    public createDefaultCategoryOptions(category: string, defaultOptions: ISoundPlayOptions): void {
        this.categoryOptions[category] = defaultOptions;
    }

    protected getDefaultCategoryOptions(category: string): ISoundPlayOptions {
        return this.categoryOptions[category] ?? {};
    }

    protected getDynamicTrackController(category: string): DynamicTrackController {
        if (this.categoryDynamicTrackControllers[category] === undefined) {
            this.categoryDynamicTrackControllers[category] = new DynamicTrackController(this, category);
        }
        return this.categoryDynamicTrackControllers[category];
    }

    public getCategoryMuted(category: string): boolean {
        return this.categoryMutes[category] ?? false;
    }

    public setCategoryMuted(category: string, muted: boolean): void {
        const isMuted = this.getCategoryMuted(category);
        if (isMuted === muted) {
            return;
        }
        muted ? this.mute(category) : this.unmute(category);
    }

    public setCategoryVolume(category: string, volume: number): void {
        //clamp volume to 0 to 1 to avoid any dodgy id stuff
        volume = Math.max(0, Math.min(1, volume));
        this.categoryVolumes[category] = volume;
        this.getActiveTracksOfCategory(category)
            .forEach((instance) => {
                instance.setCategoryVolume(volume);
            });
    }

    public getActiveTracksOfCategory(category: string): SoundInstance[] {
        return Array.from(this.activeTrackList.values())
            .filter((instance) => instance.category === category);
    }

    public mute(category: string): void {
        this.categoryMutes[category] = true;
        this.getActiveTracksOfCategory(category)
            .forEach((instance) => {
                instance.setCategoryMute(true);
            });
    }

    public unmute(category: string): void {
        this.categoryMutes[category] = false;
        this.getActiveTracksOfCategory(category)
            .forEach((instance) => {
                instance.setCategoryMute(false);
            });
    }

    public pauseAll(category: string): void {
        this.getActiveTracksOfCategory(category)
            .forEach((instance) => {
                instance.pause();
            });
    }

    public resumeAll(category: string): void {
        this.getActiveTracksOfCategory(category)
            .forEach((instance) => {
                instance.resume();
            });
    }

    public stopAll(): void {
        return Array.from(this.activeTrackList.values())
            .forEach((instance) => {
                instance.stop();
            });
    }

    public stopAllInCategory(category: string): void {
        this.getActiveTracksOfCategory(category)
            .forEach((instance) => {
                instance.stop();
            });
    }

    public resume(id: number): void {
        this.getInstance(id)?.resume();
    }

    public resumeAllInstancesOf(name: string, sprite?: string): void {
        this.getAllInstancesOf(name, sprite).forEach((instance) => {
            instance.resume();
        });
    }

    public pause(id: number): void {
        this.getInstance(id)?.pause();
    }

    public pauseAllInstancesOf(name: string, sprite?: string): void {
        this.getAllInstancesOf(name, sprite).forEach((instance) => {
            instance.pause();
        });
    }

    public seek(id: number, start: number): void {
        const instance = this.getInstance(id);
        if (instance) {
            instance.seek = start;
        }
    }

    /**
     * Gets the mediaInstance of the given track ID
     * @param id the unique id to retrieve
     * @returns { SoundInstance } the soundInstance
     */
    public getInstance(id: number): SoundInstance | undefined {
        return this.activeTrackList.get(id);
    }

    public getAllInstancesOf(name: string, sprite?: string): SoundInstance[] {
        return Array.from(this.activeTrackList.values())
            .filter((instance) => {
                return instance.sound.name === name && (sprite === undefined || instance.sprite === sprite);
            });
    }

    /**
     * stops a given track id and cleans it up from the active list
     * @param id the id of the track to stop
     */
    public stop(id: number): void {
        this.getInstance(id)?.stop();
    }

    public stopAllInstancesOf(name: string, sprite?: string): void {
        this.getAllInstancesOf(name, sprite)
            .forEach((instance) => {
                instance.stop();
            });
    }

    public exists(name: string, sprite?: string): boolean {
        const sound = AssetManager.sounds[name];
        if (!sound) {
            return false;
        }
        if (!!sprite) {
            return !!sound.sprites[sprite];
        }
        return true;
    }

    public play(name: string, options: ISoundPlayCategoryOptions = { category: 'sfx' }): SoundInstance | undefined {
        if (SoundManager.contextState === 'interrupted') {
            // this is a pure mug when interrupted
            console.warn('Audio context is in an interrupted state. Playback is not possible until the context is resumed by a user gesture.');
            return;
        }

        if (this.disablePlaybackBeforeUnlock && SoundManager.contextState === 'suspended') {
            console.warn('Audio context is in a suspended state. Playback is not possible until the context is resumed by a user gesture.');
            return;
        }
        options = {
            ...this.getDefaultCategoryOptions(options.category),
            ...options,
        };

        if (!this.exists(name, options.sprite)) {
            logAudioError(`Sound with name "${name}" does not exist in category "${options.category}"`);
            return;
        }
        const sound = AssetManager.sounds[name];

        if (!sound.isLoaded) {
            logAudioError(`Sound with name "${name}" has yet to load with current state of: "${sound.state}"`);
            return;
        }

        const soundToPlay = sound.play(options.sprite);
        // eslint-disable-next-line no-console
        logAudioInfo('attempting to play sound with name: ', name, ' and sprite: ', options.sprite, ' got sound id: ', soundToPlay);
        const instance = new SoundInstance(sound, soundToPlay, {
            delayInMs: options.delayInMs,
            loop: options.loop,
            sprite: options.sprite,
            rate: options.rate,
            seek: options.seek,
            volume: options.volume,
            category: options.category,
            muted: options.muted,
            categoryMute: this.categoryMutes[options.category] ?? false,
            categoryVolume: this.categoryVolumes[options.category] ?? 1,
        });
        if (instance.isDisposed) {
            return;
        }
        this.activeTrackList.set(instance.id, instance);
        instance.on('dispose', (id) => {
            this.activeTrackList.delete(id);
        });
        return instance;
    }

    /**
     * Removes all references of the passed sound from the activeList
     * @param key the name of the track to release
     */
    public releaseSound(name: string, sprite?: string): void {
        this.getAllInstancesOf(name, sprite)
            .forEach((instance) => {
                instance.dispose();
            });
    }

    /**
     * Fades a currently playing tracks volume down to 0 and starts a new track at volume 0 increasing to 1
     * @param fromSound the currently playing track/sprite to reduce to volume 0
     * @param toSound the new track/sprite to start playing and gradually raise volume
     * @param options to control the duration of the fade plus any options for the new track
     * @returns the newly started track, or a list of the tracks with that name already playing
     */
    public crossfade(fromSound: SoundInstance | number, toSound: { name: string, options: Pick<ISoundPlayCategoryOptions, 'sprite' | 'category'> }, options?: Partial<ICrossfadeOptions>): ICrossFadeResponse | void {
        const fromInstance = typeof fromSound === 'number' ? this.getInstance(fromSound) : fromSound;
        if (!fromInstance || fromInstance.isDisposed) {
            logAudioError(`crossfade: fromSound with id ${fromSound} does not exist or has already been disposed`);
            return;
        }
        const fadeOptions = {
            ...DEFAULT_CROSSFADE_OPTIONS,
            ...options,
            playOptions: {
                ...DEFAULT_CROSSFADE_OPTIONS.playOptions,
                ...options?.playOptions
            }
        };
        const duration = fadeOptions.duration;
        const toInstance = this.play(toSound.name, { ...toSound.options, volume: 0, category: fromInstance.category });
        if (!toInstance) {
            if (toSound.options.sprite) {
                logAudioError(`crossfade: toSound with name ${toSound.name} and sprite ${toSound.options.sprite} does not exist`);
                return;
            } else {
                logAudioError(`crossfade: toSound with name ${toSound.name} does not exist`);
                return;
            }
        }

        const tl = new gsap.core.Timeline({})
            .fromTo(fromInstance, {
                volume: fromInstance.volume
            }, {
                volume: 0,
                duration
            })
            .fromTo(toInstance, {
                volume: 0
            }, {
                volume: fadeOptions.playOptions.volume ?? 1,
                duration
            }, 0);

        fromInstance.once('dispose', () => {
            gsap.killTweensOf(fromInstance);
        });
        toInstance.once('dispose', () => {
            gsap.killTweensOf(toInstance);
        });

        return {
            to: toInstance,
            from: fromInstance,
            timeline: tl
        };
    }

    public fade(id: number, options?: Partial<IFadeOptions>): gsap.core.Timeline | undefined {
        const fadeOptions = { ...DEFAULT_FADE_OPTIONS, ...options };
        const { duration } = fadeOptions;
        const instance = this.getInstance(id);

        if (instance) {
            const tween = new gsap.core.Timeline({}).to(instance, {
                duration,
                volume: fadeOptions.toVolume
            });
            instance.once('dispose', () => {
                gsap.killTweensOf(instance);
            });
            return tween;
        }
    }

    public playDynamic(category: string, trackNames: string[], options?: Partial<IDynamicSoundOptions>): void {
        return this.getDynamicTrackController(category).playDynamic(trackNames, options);
    }

    public stopDynamic(category: string): void {
        return this.getDynamicTrackController(category).stopDynamic();
    }

    public getCurrentDynamicTrack(category: string): SoundInstance | undefined {
        return this.getDynamicTrackController(category).currentInstance;
    }
}